const b = new Array(N).fill(0);
const c = new Array(N).fill(0);
const z = new Array(N).fill(0);
const A = new Array(N).fill(0);
const B = new Array(N).fill(0);

function mulmod(x, y) {
    const hi = Math.floor(x / 65536), lo = x % 65536;
    return ((hi * y % mod) * 65536 + lo * y) % mod;
}

function inc(arr, idx, y) {
    const v = arr[idx] + y;
    arr[idx] = v >= mod ? v - mod : v;
}

function mult(u, v) {
    z.fill(0);
    for (let i = 0; i <= 249; i++) {
        if (u[i] === 0) continue;
        for (let j = 0; j <= 249; j++) {
            if (v[j] === 0) continue;
            z[i + j] = (z[i + j] + mulmod(u[i], v[j])) % mod;
        }
    }
    for (let i = 498; i >= 250; i--)
        for (let j = 1; j <= m; j++) inc(z, i - b[j], z[i]);
    for (let i = 0; i <= 249; i++) u[i] = z[i];
}

function ksm(cc, e) {
    A.fill(0);
    A[0] = 1;
    let nn = e;
    while (nn > 0n) {
        if (nn & 1n) mult(A, cc);
        nn >>= 1n;
        mult(cc, cc);
    }
}

function main() {
    n = parseInt(data[ptr++]);
