        ksm(c, BigInt(a[i]));
        for (let j = 0; j <= 249; j++) inc(B, j, A[j]);
    }
    ksm(B, K);
    for (let i = 0; i <= 249; i++) B[i] = A[i];
    for (let i = 249; i > 0; i--)
        for (let j = 1; j <= m; j++)
            if (i >= b[j]) inc(B, i - b[j], B[i]);
    console.log(B[0]);
}

main();
